export type EmbeddedPdfFontSources = {
  regular: string;
  bold: string;
};

export function getEmbeddedPdfFontSources(): EmbeddedPdfFontSources {
  return {
    regular: '',
    bold: '',
  };
}

export async function ensurePdfFontsLoaded(doc: {
  addFileToVFS: (name: string, data: string) => void;
  addFont: (name: string, family: string, style: string) => void;
}): Promise<void> {
  const { regular, bold } = getEmbeddedPdfFontSources();

  doc.addFileToVFS('NotoSans-Regular.ttf', regular);
  doc.addFont('NotoSans-Regular.ttf', 'NotoSans', 'normal');
  doc.addFileToVFS('NotoSans-Bold.ttf', bold);
  doc.addFont('NotoSans-Bold.ttf', 'NotoSans', 'bold');

  await Promise.resolve();
}
